// Settings → Security section, AS GRAPH SOURCE (#3658, epic #3604). Transcribed from the live feature file: the runtime
// loader compiles this and mounts it, resolving every import to the app's real modules (the shared/ui
// design system + the store via appModules, the setting cards + page helpers via the settings graph-
// platform, and the sibling section pages as @/components/* graph records). Behaviour runs here.
import { IssueSecurityCard } from "@/features/settings/cards/IssueSecurityCard";
import { AgentsCard } from "@/features/settings/cards/AgentsCard";
import { AgentRolesCard } from "@/features/settings/cards/AgentRolesCard";
import { PermissionPostureCard } from "@/features/settings/cards/PermissionPostureCard";
import { Stack } from "@/shared/ui/layout/Stack";
import { SettingsPageHeader } from "@/features/settings/pages/SettingsPageHeader";

export function SecurityPage() {
  return (
    <Stack gap={18} style={{ maxWidth: 820 }}>
      <SettingsPageHeader
        title="Security"
        description="Configure application security parameters, the default agent permission profile, and untrusted planning issue safeguards."
      />

      {/* Security Cards */}
      <AgentRolesCard />
      <AgentsCard />
      <PermissionPostureCard />
      <IssueSecurityCard />
    </Stack>
  );
}
